CREATE TABLE community_groups (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, description VARCHAR(500), creator_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE group_members (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES community_groups(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(group_id,user_id));
